const sensoryGames=[
{id:281,type:"Juego sensorial",categories:["Percepción auditiva","Orientación espacial","Juegos inclusivos"],title:"Radar de cascabeles",cycle:"1.º ciclo",goals:["Localización auditiva","Orientación"],material:"Material específico",intensity:"Baja",duration:9,group:"Pequeños grupos",color:"blue",summary:"Desde una posición fija, el alumnado localiza con el oído el lugar desde el que suena un cascabel y señala su dirección.",setup:"Forma grupos de cuatro; una persona se sitúa sentada o de pie dentro de un aro y las demás ocupan tres marcas alrededor.",rules:["Cierra los ojos únicamente cuando estés quieto dentro del aro.","Una compañera hace sonar el cascabel una vez desde su marca.","Señala la dirección del sonido, abre los ojos para comprobar y cambia de función."],variant:"Distingue sonidos cercanos y lejanos o utiliza dos instrumentos diferentes.",observation:"Ofrece también la opción de mantener los ojos abiertos y mirar al suelo.",safety:"Sin desplazamiento con ojos cerrados, volumen suave y marcas alejadas de obstáculos.",image:"images/games/281-radar-cascabeles.webp"},
{id:282,type:"Juego sensorial",categories:["Percepción táctil","Esquema corporal"],title:"La bolsa misteriosa",cycle:"1.º ciclo",goals:["Discriminación táctil","Lenguaje descriptivo"],material:"Material específico",intensity:"Baja",duration:10,group:"Parejas",color:"green",summary:"Las manos exploran dentro de una bolsa opaca y reconocen objetos deportivos por su forma, textura y flexibilidad.",setup:"Prepara bolsas opacas con objetos seguros: pelota de espuma, cuerda gruesa, saquito, aro pequeño y pañuelo.",rules:["Introduce una mano sin mirar el contenido.","Describe lo que notas —duro, blando, liso, rugoso, redondo— antes de decir qué objeto crees que es.","Saca el objeto para comprobar y entrega la bolsa a tu pareja."],variant:"Busca dos objetos con una cualidad común o identifica solo mediante tres preguntas.",observation:"No es necesario acertar; importa verbalizar las sensaciones que permiten decidir.",safety:"Objetos limpios, grandes, sin bordes ni piezas pequeñas y una bolsa por pareja.",image:"images/games/282-bolsa-misteriosa.webp"},
{id:283,type:"Juego sensorial",categories:["Percepción táctil","Equilibrio"],title:"Camino de texturas",cycle:"1.º ciclo",goals:["Discriminación táctil","Equilibrio dinámico"],material:"Material específico",intensity:"Baja",duration:11,group:"Individual",color:"orange",summary:"Un sendero de superficies seguras permite comparar sensaciones al caminar lentamente con calcetines o al explorarlas con las manos.",setup:"Coloca alfombrillas antideslizantes de goma, espuma, césped artificial suave, tela y relieve ancho.",rules:["Recorre el camino despacio mirando al frente y con los pies protegidos.","Detente en cada superficie y elige dos palabras para describirla.","Al terminar, toca con la mano dos texturas y ordénalas de más suave a más rugosa."],variant:"Realiza el camino con pasos laterales o busca dos texturas parecidas.",observation:"Cada participante puede omitir cualquier superficie que le resulte desagradable.",safety:"Sin pies descalzos, materiales limpios y fijados al suelo, sin elementos duros o punzantes.",image:"images/games/283-camino-texturas.webp"},
{id:284,type:"Juego sensorial",categories:["Percepción auditiva","Ritmo y percepción temporal","Coordinación"],title:"Eco de pasos",cycle:"1.º ciclo",goals:["Memoria auditiva","Ritmo"],material:"Sin material",intensity:"Media",duration:9,group:"Gran grupo",color:"yellow",summary:"El grupo escucha una breve secuencia de pasos, palmadas y golpes suaves en muslos y la reproduce sin apoyo visual.",setup:"Sitúa al alumnado en semicírculo y deja a la persona guía tras una pequeña pantalla o de espaldas.",rules:["Escucha en silencio una secuencia de dos o tres sonidos corporales.","Reprodúcela respetando orden, pausas e intensidad.","La guía se muestra, repite la solución y cede el turno a otra persona."],variant:"Diferencia sonido fuerte y suave o responde con una secuencia distinta del mismo pulso.",observation:"Empieza con sonidos muy contrastados antes de introducir matices.",safety:"Golpes suaves sobre el propio cuerpo y volumen moderado.",image:"images/games/284-eco-pasos.webp"},
{id:285,type:"Juego sensorial",categories:["Percepción visual","Coordinación","Vuelta a la calma"],title:"Pañuelos a cámara lenta",cycle:"1.º ciclo",goals:["Seguimiento visual","Control respiratorio"],material:"Material específico",intensity:"Baja",duration:8,group:"Parejas",color:"blue",summary:"Una persona mueve un pañuelo lentamente por diferentes trayectorias y la pareja lo sigue solo con la mirada y después con una mano.",setup:"Forma parejas sentadas o de pie en marcas separadas y entrega un pañuelo ligero de color vivo.",rules:["Mueve el pañuelo despacio de izquierda a derecha, arriba y abajo, sin acercarlo a la cara.","La pareja mantiene la cabeza quieta y sigue el recorrido con los ojos.","En la segunda ronda acompaña la trayectoria con una mano y cambia de función."],variant:"Dibuja círculos, ochos amplios o detenciones inesperadas.",observation:"Incluye pausas para descansar la vista y evita exigir fijación prolongada.",safety:"Distancia de un brazo, movimientos lentos y ninguna luz intensa o parpadeante.",image:"images/games/285-panuelos-lentos.webp"},
{id:286,type:"Juego sensorial",categories:["Percepción propioceptiva","Toma de decisiones"],title:"Ordena los pesos",cycle:"2.º ciclo",goals:["Discriminación de peso","Dosificación de fuerza"],material:"Material específico",intensity:"Baja",duration:10,group:"Pequeños grupos",color:"green",summary:"El alumnado compara saquitos de igual tamaño y diferente peso para ordenarlos usando únicamente la información de manos y brazos.",setup:"Prepara series de tres o cuatro saquitos cerrados, visualmente iguales y con diferencias de peso pequeñas pero claras.",rules:["Levanta cada saquito con ambas manos sin lanzarlo.","Compáralos de dos en dos y colócalos del más ligero al más pesado.","Comprueba las marcas de la base y explica qué sensaciones te ayudaron."],variant:"Busca dos pesos semejantes o repite usando una sola mano y luego la otra.",observation:"Las cargas deben ser ligeras y adecuadas a Primaria; se compara, no se trabaja fuerza máxima.",safety:"Saquitos completamente cerrados, levantados cerca del cuerpo y nunca por encima de los hombros.",image:"images/games/286-ordena-pesos.webp"},
{id:287,type:"Juego sensorial",categories:["Percepción propioceptiva","Esquema corporal"],title:"Fuerza exacta",cycle:"2.º ciclo",goals:["Regulación de fuerza","Conciencia corporal"],material:"Material específico",intensity:"Baja",duration:10,group:"Parejas",color:"orange",summary:"La pareja intenta reproducir tres niveles de presión empujando una pelota grande contra la pared o una colchoneta vertical.",setup:"Coloca pelotas grandes de espuma frente a una pared protegida y prepara señales visuales de presión suave, media y algo más firme.",rules:["Apoya ambas manos sobre la pelota sin mover los pies.","Presiona durante tres segundos con la intensidad mostrada y relaja por completo.","Tu pareja observa el hundimiento o movimiento, ofrece una indicación y después cambia de función."],variant:"Presiona con antebrazos, espalda o una mano, siempre con intensidad cómoda.",observation:"Se aprende a diferenciar intensidades, no a competir por aplicar más fuerza.",safety:"Pelotas blandas, pared protegida, articulaciones sin bloqueo y nada de empujes entre personas.",image:"images/games/287-fuerza-exacta.webp"},
{id:288,type:"Juego sensorial",categories:["Percepción auditiva","Juegos inclusivos","Juegos con balón"],title:"Pelota sonora por parejas",cycle:"1.º ciclo",goals:["Seguimiento auditivo","Recepción"],material:"Balones",intensity:"Baja",duration:10,group:"Parejas",color:"yellow",summary:"Una pelota con cascabel interior rueda entre dos personas, que escuchan su trayectoria antes de detenerla suavemente.",setup:"Forma parejas sentadas con piernas separadas o de rodillas a poca distancia y entrega una pelota sonora.",rules:["Di el nombre de tu pareja antes de rodar la pelota.","Hazla rodar por el suelo a velocidad suave y escucha su recorrido.","La pareja la detiene con ambas manos, confirma que la tiene y la devuelve."],variant:"Coloca una puerta ancha entre ambos o trabaja con una persona mirando al suelo y otra guiando con la voz.",observation:"Juego útil para compartir estrategias de orientación de alumnado con y sin discapacidad visual.",safety:"Pelota siempre rodada, distancia corta, espacio despejado y sin antifaces.",image:"images/games/288-pelota-sonora.webp"},
{id:289,type:"Juego sensorial",categories:["Percepción vestibular","Equilibrio","Vuelta a la calma"],title:"Balanceo y pausa",cycle:"1.º ciclo",goals:["Percepción vestibular","Control postural"],material:"Colchonetas",intensity:"Baja",duration:8,group:"Individual",color:"blue",summary:"Sentado sobre una colchoneta, cada participante realiza pequeños balanceos y se detiene para reconocer cuándo su cuerpo vuelve a estar estable.",setup:"Distribuye colchonetas finas separadas y sitúa al alumnado sentado con pies apoyados.",rules:["Balancea el tronco suavemente hacia delante, atrás y a ambos lados sin levantar los pies.","Detente cuando suene una palmada y nota cómo recuperas la vertical.","Señala con una mano la dirección del último balanceo y respira antes de repetir."],variant:"Realiza círculos muy pequeños o trabaja en cuadrupedia trasladando lentamente el peso.",observation:"Quien sienta mareo permanece quieto y observa; nunca se fuerza la experiencia.",safety:"Movimientos de poca amplitud, sin giros rápidos, cabeza cómoda y pausas frecuentes.",image:"images/games/289-balanceo-pausa.webp"},
{id:290,type:"Juego sensorial",categories:["Percepción auditiva","Memoria"],title:"Parejas de sonidos",cycle:"2.º ciclo",goals:["Discriminación auditiva","Memoria sensorial"],material:"Material específico",intensity:"Baja",duration:11,group:"Pequeños grupos",color:"green",summary:"Pequeños recipientes opacos forman parejas por el sonido de su contenido y deben emparejarse sin abrirlos.",setup:"Prepara botes dobles, bien sellados y diferenciados solo en la base, con arroz, pasta grande, cascabeles o cuentas gruesas.",rules:["Agita un bote cerca del pecho durante un segundo y escucha.","Compara con otro bote y decide si ambos sonidos forman pareja.","Colócalos juntos; al final comprueba las marcas inferiores y corrige si es necesario."],variant:"Ordena sonidos de más suave a más intenso o distingue contenidos con ritmos de agitación iguales.",observation:"Conviene usar cuatro parejas al inicio y aumentar solo cuando haya estrategias de comparación.",safety:"Botes irrompibles y sellados, volumen moderado y nunca junto al oído.",image:"images/games/290-parejas-sonidos.webp"}
];
